'use strict';
function main(){
var e=2.0;
var cats=[[4,1],[8,2],[25,3],[40,4]];
var cat=null;
for(var i=0;i<cats.length;i++){if(e<=cats[i][0]){cat=cats[i][1];break;}}
return {incident_energy_cal_cm2:e, ppe_category:cat, note:cat?"dress to category":"energy exceeds Cat 4 — re-engineer"};
}
try{var out=main();console.log(JSON.stringify(out));}catch(e){console.log(JSON.stringify({error:String(e&&e.message||e)}));process.exitCode=1;}

